WITH flattened AS (SELECT id, service, host, log_ts, level, latency_ms, k, value FROM app_logs LATERAL VIEW OUTER EXPLODE(context) li AS k, value) SELECT CASE WHEN latency_ms >= 2368 THEN 'HIGH' ELSE 'LOW' END AS latency_ms_tier, DATE_TRUNC('HOUR', log_ts) AS hour_window, MAX(log_ts) AS ended_at, COUNT(CASE WHEN service = 'auth' THEN 1 END) AS auth_count, COUNT(DISTINCT k) AS distinct_ks, SIZE(COLLECT_SET(k)) AS num_ks FROM flattened GROUP BY 1, 2 ORDER BY hour_window DESC
